class Account {
    private int balance;          // campo: dado de cada objeto
    Account(int start) {          // construtor: roda quando o objeto nasce
        this.balance = start;
    }
    int balance() { return balance; }
}
Account a = new Account(10);
Account b = new Account(99);      // independente de a

abstract class Game {
    final void play() {          // a ordem é fixa
        start(); turn(); end();
    }
    void start() { }             // passo opcional
    abstract void turn();        // cada jogo preenche este
    void end() { }
}

class Car {
    private final Engine engine;      // tem-um
    Car(Engine engine) { this.engine = engine; }
    void start() { engine.ignite(); } // delega
}

static int value() {
    int x = 1;
    try { x = 2; return x; }   // o resultado 2 é guardado antes
    finally { x = 3; }         // tarde demais para mudá-lo
}                              // devolve 2

interface Priced { price: number }
class Book { constructor(public price: number) {} }
const items: Priced[] = [new Book(10), { price: 5 }];   // os dois são aceitos
